\begin{lemma} 
	$$	\lim_{k \to \infty}- \frac{1}{k} \log \left[\mu((x_k(\theta_1) - x_k(\theta_2)) \leq 0 | \theta_1 , \theta_2)\right] = \inf_{a \in \mathcal{R}} \left \{ g(\theta_1) I(a|\theta_1) + g(\theta_2) I(a|\theta_2) \right \}$$ where $I(a|\ell) = \sup_z \{ za - \Lambda(z|\theta) \}$, $\Lambda(z|\theta)$ is the log moment generating function of a single sample from $x(\theta_1)$, and $g(\theta)$ is the sampling rate. \label{lem:problessthan}
\end{lemma}

Let $y_0(\theta), y_1(\theta), y_2(\theta), \ldots$ be the sequence of ratings received by the seller of type $\theta$.  The {\em aggregate score} up to time $k$ of this seller is the average score from ratings received:
\begin{equation}
\label{eq:aggscore}
 x_k(\theta) =  \frac{1}{n_k(\theta)} \sum_{\ell = 0}^{n_k(\theta)} \phi(y_\ell(\theta)).
\end{equation}
(We presume $x_0(\theta) = 0$ for all $\theta$.)  Since $\phi(y) \in [0,1]$ for all $y$, the score $x_k$ also lies in $[0,1]$.

